  p_Description_c5c9502d240a := 'Ask whether the calling user can execute one or more named MJ: Authorizations, including ancestor grants. Unknown names fail closed (Allowed=false, Unknown=true). When a row has UseAuditLog, a MJ: Audit Logs record is written. Implemented by AuthorizationCheckOperation in @memberjunction/core-entities.';
  p_InputTypeName_c5c9502d240a := 'AuthorizationCheckInput';
  p_InputTypeDefinition_c5c9502d240a := '/** Input for `Authorization.Check`. */
export interface AuthorizationCheckInput {
    /**
     * Authorization names to evaluate (e.g. `Orders.Price.OverrideList`).
     * Matching is case-insensitive. Empty array returns an empty Results list.
     */
